def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[r[:] for r in grid]
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            comp=[]; stack=[(r,c)]; seen.add((r,c))
            while stack:
                x,y=stack.pop(); comp.append((x,y))
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and grid[a][b]!=0 and (a,b) not in seen:
                        seen.add((a,b)); stack.append((a,b))
            rows={}
            for x,y in comp: rows.setdefault(x,set()).add(grid[x][y])
            if any(len(s)>1 for s in rows.values()):
                for x,y in comp: out[x][y]=0
    return out

